using System;
using System.Collections.Generic;
using JetBrains.Annotations;
using Kingmaker.Blueprints;
using Kingmaker.Controllers.Units;
using Kingmaker.ElementsSystem;
using Kingmaker.EntitySystem;
using Kingmaker.EntitySystem.Entities;
using Kingmaker.EntitySystem.Persistence.JsonUtility;
using Kingmaker.QA;
using Kingmaker.RandomEncounters.Settings;
using Kingmaker.ResourceLinks;
using Kingmaker.UnitLogic.Parts;
using Kingmaker.Utility;
using Newtonsoft.Json;
using Owlcat.QA.Validation;
using Owlcat.Runtime.Core.Utils;
using UnityEngine;

namespace Kingmaker.View.Spawners;

public abstract class UnitSpawnerBase : EntityViewBase
{
	public class MyData : StaticEntityData
	{
		[JsonProperty]
		private UnitReference m_SpawnedUnit;

		[JsonProperty]
		public bool HasSpawned { get; set; }

		[JsonProperty(DefaultValueHandling = DefaultValueHandling.IgnoreAndPopulate)]
		public bool HasDied { get; set; }

		public UnitReference SpawnedUnit
		{
			get
			{
				return m_SpawnedUnit;
			}
			set
			{
				if (m_SpawnedUnit != value)
				{
					if (m_SpawnedUnit != null)
					{
						Clear();
					}
					m_SpawnedUnit = value;
					OnSpawned();
				}
			}
		}

		public override bool IsViewActive => true;

		public MyData(EntityViewBase view)
			: base(view)
		{
		}

		protected MyData(JsonConstructorMark _)
			: base(_)
		{
		}

		public virtual bool ShouldProcessActivation(bool alsoRaiseDead)
		{
			UnitSpawnerBase unitSpawnerBase = (UnitSpawnerBase)base.View;
			if (!unitSpawnerBase)
			{
				return false;
			}
			if (unitSpawnerBase.SpawnOnSceneInit)
			{
				if (unitSpawnerBase.HasSpawned)
				{
					if (alsoRaiseDead && unitSpawnerBase.m_RespawnIfDead)
					{
						return unitSpawnerBase.SpawnedUnitHasDied;
					}
					return false;
				}
				return true;
			}
			return false;
		}

		protected virtual void OnSpawned()
		{
			if (SpawnedUnit.Value != null)
			{
				ApplyOnSpawn();
				HasSpawned = true;
			}
		}

		public void ApplyOnSpawn()
		{
			foreach (IUnitInitializer item in Parts.GetAll<IUnitInitializer>())
			{
				item.OnSpawn(SpawnedUnit);
				item.OnInitialize(SpawnedUnit);
			}
		}

		protected override void OnViewDidAttach()
		{
			base.OnViewDidAttach();
			UnitEntityData value = SpawnedUnit.Value;
			if (!(value != null))
			{
				return;
			}
			foreach (IUnitInitializer item in Parts.GetAll<IUnitInitializer>())
			{
				if (value.IsRestoredFromPlaceholder && item.CallOnSpawnWhenRestoredFromPlaceholder)
				{
					item.OnSpawn(value);
				}
				item.OnInitialize(value);
			}
			if ((value.SpawnPosition.To2D() - value.Position.To2D()).magnitude < 0.1f)
			{
				Vector3 spawnPosition = (value.Position = base.View.transform.position);
				value.SpawnPosition = spawnPosition;
				value.Orientation = base.View.transform.rotation.eulerAngles.y;
			}
		}

		protected override void OnDispose()
		{
			Clear();
			base.OnDispose();
		}

		public void Clear()
		{
			ApplyOnDispose();
			m_SpawnedUnit = null;
			HasSpawned = false;
		}

		public void ApplyOnDispose()
		{
			UnitEntityData unit = SpawnedUnit.Value;
			if (unit != null && !unit.DestroyMark && !unit.Destroyed)
			{
				Parts.GetAll<IUnitInitializer>().ForEach(delegate(IUnitInitializer d)
				{
					d.OnDispose(unit);
				});
			}
		}

		protected override void OnIsInGameChanged()
		{
			base.OnIsInGameChanged();
		}

		public void DetachSpawned(bool allowRespawn = false)
		{
			SpawnedUnit = null;
			bool flag = (base.View as UnitSpawnerBase)?.m_RespawnIfDead ?? false;
			bool flag2 = allowRespawn && flag;
			HasSpawned = !flag2;
		}
	}

	[SerializeField]
	[ValidateNotNull]
	private BlueprintUnitReference m_Blueprint;

	[SerializeField]
	private bool m_SpawnOnSceneInit = true;

	[InfoBox("Respawn only on area load if SpawnOnSceneInit = true")]
	[SerializeField]
	[HideIf("SpawnsCompanions")]
	private bool m_RespawnIfDead;

	[SerializeField]
	private ConditionsReference m_spawnConditions;

	private bool SpawnsCompanions => this is CompanionSpawner;

	public bool HasSpawned
	{
		get
		{
			return Data.HasSpawned;
		}
		protected set
		{
			Data.HasSpawned = value;
		}
	}

	public BlueprintUnit Blueprint
	{
		get
		{
			return m_Blueprint?.Get();
		}
		set
		{
			m_Blueprint = value.ToReference<BlueprintUnitReference>();
		}
	}

	public UnitEntityData SpawnedUnit
	{
		get
		{
			UnitReference? unitReference = Data?.SpawnedUnit;
			if (!unitReference.HasValue)
			{
				return null;
			}
			return unitReference.GetValueOrDefault();
		}
	}

	public bool SpawnOnSceneInit => m_SpawnOnSceneInit;

	public bool SpawnedUnitHasDied
	{
		get
		{
			if (HasSpawned)
			{
				return SpawnedUnit?.State.IsDead ?? Data.HasDied;
			}
			return false;
		}
	}

	public new MyData Data => (MyData)base.Data;

	public override bool CreatesDataOnLoad => true;

	public virtual void HandleAreaSpawnerInit()
	{
		if (Game.Instance.CurrentlyLoadedArea.GetComponent<CombatRandomEncounterAreaSettings>() == null && (!HasSpawned || (SpawnedUnitHasDied && m_RespawnIfDead)) && m_SpawnOnSceneInit && CheckConditions())
		{
			if (!(Data.SpawnedUnit.Value?.Get<UnitPartCompanion>()))
			{
				Data.SpawnedUnit.Value?.MarkForDestroy();
			}
			Data.Clear();
			Spawn();
		}
	}

	public bool CheckConditions()
	{
		if (m_spawnConditions.Get() != null)
		{
			ConditionsChecker conditions = m_spawnConditions.Get().Conditions;
			if (conditions.HasConditions)
			{
				return conditions.Check();
			}
			return true;
		}
		return true;
	}

	[CanBeNull]
	public UnitEntityData Spawn()
	{
		if (HasSpawned)
		{
			PFLog.Default.Warning("Trying to use spawner {0} twice.", base.name);
			return null;
		}
		if (m_Blueprint.IsEmpty())
		{
			PFLog.Default.ErrorWithReport("UnitSpawnerBase.Spawn: unit blueprint is null! " + base.name);
			return null;
		}
		List<IUnitSpawnRestriction> list = TempList.Get<IUnitSpawnRestriction>();
		GetComponents(list);
		UnitSpawnRestrictionResult unitSpawnRestrictionResult = UnitSpawnRestrictionResult.CanSpawn;
		foreach (IUnitSpawnRestriction item in list)
		{
			UnitSpawnRestrictionResult unitSpawnRestrictionResult2 = item.CanSpawn();
			if (unitSpawnRestrictionResult2 > unitSpawnRestrictionResult)
			{
				unitSpawnRestrictionResult = unitSpawnRestrictionResult2;
			}
		}
		switch (unitSpawnRestrictionResult)
		{
		case UnitSpawnRestrictionResult.Delay:
			return null;
		case UnitSpawnRestrictionResult.Disable:
			HasSpawned = true;
			return null;
		default:
		{
			UnitEntityData unitEntityData = SpawnUnit(base.transform.position, base.transform.rotation);
			if (unitEntityData == null)
			{
				return null;
			}
			Data.SpawnedUnit = unitEntityData;
			unitEntityData.SpawnPosition = base.transform.position;
			unitEntityData.GiveExperienceOnDeath = unitEntityData.GiveExperienceOnDeath && !Data.HasDied;
			UnitPlaceOnGroundController.ForcedTick(unitEntityData);
			return unitEntityData;
		}
		}
	}

	public UnitEntityData TrySpawnOrRespawn()
	{
		if (!HasSpawned || SpawnedUnitHasDied)
		{
			if (!(Data.SpawnedUnit.Value?.Get<UnitPartCompanion>()))
			{
				Data.SpawnedUnit.Value?.MarkForDestroy();
			}
			Data.Clear();
			return Spawn();
		}
		return null;
	}

	[CanBeNull]
	public UnitEntityData ForceReSpawn()
	{
		Data.SpawnedUnit.Value?.MarkForDestroy();
		Data.Clear();
		UnitEntityData unitEntityData = SpawnUnit(base.transform.position, base.transform.rotation);
		if (unitEntityData == null)
		{
			return null;
		}
		Data.SpawnedUnit = unitEntityData;
		unitEntityData.SpawnPosition = base.transform.position;
		UnitPlaceOnGroundController.ForcedTick(unitEntityData);
		return unitEntityData;
	}

	public override EntityDataBase CreateEntityData(bool load)
	{
		return new MyData(this);
	}

	protected virtual UnitEntityData SpawnUnit(Vector3 position, Quaternion rotation)
	{
		return null;
	}

	[NotNull]
	protected UnitViewLink SelectPrefab()
	{
		if (Blueprint == null)
		{
			throw new Exception("UnitSpawner.SelectPrefab: missing blueprint");
		}
		if (Blueprint.Prefab == null)
		{
			throw new Exception("UnitSpawner.SelectPrefab: prefab is null");
		}
		return Blueprint.Prefab;
	}
}
