using System;
using Kingmaker.ElementsSystem;
using Kingmaker.EntitySystem.Entities;
using Kingmaker.PubSubSystem;
using Kingmaker.Utility;
using Owlcat.Runtime.Core.Utils;
using UnityEngine;

namespace Kingmaker.View.Spawners;

public class UnitSpawner : UnitSpawnerBase, IUnitHandler, IGlobalSubscriber, ISubscriber, IUnitSpawnHandler, IUnitSpawnOnlyHandler
{
	private string m_GroupId;

	private bool m_GroupIsDisabledOnSimplified;

	public bool IgnoreInEncoutnerStatistic;

	public void SetGroupView(UnitGroupView group)
	{
		m_GroupId = group.UniqueId;
		m_GroupIsDisabledOnSimplified = group.DisableOnSimplified;
	}

	protected override UnitEntityData SpawnUnit(Vector3 position, Quaternion rotation)
	{
		if (BuildModeUtility.Data?.Loading?.IgnoreSpawners == true)
		{
			return null;
		}
		if (m_GroupIsDisabledOnSimplified)
		{
			base.HasSpawned = true;
			return null;
		}
		SpawnerOptimizedUnit component = GetComponent<SpawnerOptimizedUnit>();
		SpawnerRestrictVariations component2 = GetComponent<SpawnerRestrictVariations>();
		UnitEntityData unitEntityData;
		using (UnitSpawningData unitSpawningData = ContextData<UnitSpawningData>.RequestIf((bool)component || (bool)component2))
		{
			SpawnerOptimizedUnit spawnerOptimizedUnit = component.Or(null);
			if ((object)spawnerOptimizedUnit != null && spawnerOptimizedUnit.SkipSpawnBecauseOfConsole)
			{
				base.HasSpawned = true;
				return null;
			}
			if ((bool)component && unitSpawningData != null)
			{
				unitSpawningData.MarkHiddenOptimization(component.SimplifyWhenHidden);
				unitSpawningData.MarkSpawnHidden(component.SpawnHidden);
			}
			if ((bool)component2)
			{
				if (component2.RestrictAllVariations)
				{
					unitSpawningData?.SetRestrictVariations(restrictVariations: true);
				}
				else
				{
					unitSpawningData?.SetRace(component2.GetValidRace());
				}
			}
			unitEntityData = Game.Instance.EntityCreator.SpawnUnit(base.Blueprint, position, rotation, base.Data.HoldingState);
		}
		if (unitEntityData == null)
		{
			return null;
		}
		if (!string.IsNullOrEmpty(m_GroupId))
		{
			unitEntityData.GroupId = m_GroupId;
		}
		return unitEntityData;
	}

	public void HandleUnitSpawned(UnitEntityData entityData)
	{
	}

	public void HandleUnitDestroyed(UnitEntityData entityData)
	{
		if (base.Data == null)
		{
			m_AfterAttachData = (Action)Delegate.Combine(m_AfterAttachData, (Action)delegate
			{
				HandleUnitDestroyed(entityData);
			});
		}
		else if (base.HasSpawned && entityData == base.SpawnedUnit)
		{
			base.Data.HasDied = true;
		}
	}

	public void HandleUnitDeath(UnitEntityData entityData)
	{
	}

	public void HandleUnitDeathForSpawnOnly(UnitEntityData entityData)
	{
		if (base.Data == null)
		{
			m_AfterAttachData = (Action)Delegate.Combine(m_AfterAttachData, (Action)delegate
			{
				HandleUnitDeathForSpawnOnly(entityData);
			});
		}
		else if (base.HasSpawned && entityData == base.SpawnedUnit)
		{
			base.Data.HasDied = true;
		}
	}
}
