namespace Kingmaker.UnitLogic;

public class UnitDescriptor : IDisposable
{
	public class FactionSwitcher
	{
		private bool IsStarted;

		public UnitDescriptor UnitDescriptor { get; private set; }

		public BlueprintFaction Faction { get; private set; }

		public bool ResetAttackFactions { get; private set; }

		public FactionSwitcher(UnitDescriptor unitDescriptor, BlueprintFaction faction, bool resetAttackFactions)
		{
			UnitDescriptor = unitDescriptor;
			Faction = faction;
			ResetAttackFactions = resetAttackFactions;
		}

		public void Start()
		{
			if (!IsStarted)
			{
				IsStarted = true;
				UnitDescriptor.SwitchFactions(Faction, ResetAttackFactions, permanently: false);
				UnitDescriptor.FactionSwitchers.Add(this);
			}
		}

		public void Stop()
		{
			if (IsStarted)
			{
				IsStarted = false;
				UnitDescriptor.FactionSwitchers.Remove(this);
				BlueprintFaction faction = ((UnitDescriptor.FactionSwitchers.Count > 0) ? UnitDescriptor.FactionSwitchers.Last().Faction : UnitDescriptor.FactionOriginal);
				UnitDescriptor.SwitchFactions(faction, ResetAttackFactions, permanently: false);
			}
		}
	}

	[JsonProperty]
	public ItemsCollection m_Inventory;

	[JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
	private int m_Damage;

	[NotNull]
	[JsonProperty]
	private readonly Dictionary<BlueprintSpellbook, Spellbook> m_Spellbooks = new Dictionary<BlueprintSpellbook, Spellbook>();

	[JsonProperty(PropertyName = "Faction")]
	private BlueprintFaction m_Faction;

	[JsonProperty]
	public readonly CharacterStats Stats;

	[JsonProperty]
	public readonly UnitAttackFactions AttackFactions;

	[JsonProperty]
	public readonly UnitAbilityResourceCollection Resources;

	[NotNull]
	[JsonProperty]
	public readonly UnitProgressionData Progression;

	[JsonProperty]
	public readonly UnitUISettings UISettings;

	[JsonProperty]
	public readonly UnitState State;

	[JsonProperty]
	public readonly UnitProficiency Proficiencies = new UnitProficiency();

	[JsonProperty]
	public readonly UnitAlignment Alignment;

	[JsonProperty(NullValueHandling = NullValueHandling.Ignore)]
	[CanBeNull]
	public Gender? CustomGender;

	[JsonProperty(NullValueHandling = NullValueHandling.Ignore)]
	[CanBeNull]
	public bool? LeftHandedOverride;

	[DefaultValue("")]
	[JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
	public string CustomName = "";

	[JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
	[CanBeNull]
	public BlueprintUnitAsksList CustomAsks;

	[JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
	[CanBeNull]
	public BlueprintUnitAsksList OverrideAsks;

	[JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
	public bool ForceUseClassEquipment;

	[DefaultValue(-1)]
	[JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
	public int BirthDay = -1;

	[DefaultValue(-1)]
	[JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
	public int BirthMonth = -1;

	[DefaultValue("")]
	[JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
	[NotNull]
	public string CustomPrefabGuid = "";

	[JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
	[CanBeNull]
	private List<string> m_AppliedFixers;

	[JsonProperty]
	private readonly CountableFlag m_IsEssentialForGame = new CountableFlag();

	[CanBeNull]
	private DollData m_LoadedDollData;

	private MechanicsContext m_Context;

	private bool? m_IsPlayerFactionCached;

	private BlueprintFaction m_FactionOriginal;

	private List<FactionSwitcher> FactionSwitchers = new List<FactionSwitcher>();

	[JsonProperty]
	public UnitBody Body { get; set; }

	[JsonProperty(DefaultValueHandling = DefaultValueHandling.Ignore)]
	public BlueprintUnit ReplaceBlueprintForInspection { get; set; }

	[JsonProperty]
	public UnitBrain Brain { get; private set; }

	[JsonProperty]
	public BlueprintUnit OriginalBlueprint { get; private set; }

	[JsonProperty]
	public BlueprintUnit Blueprint { get; private set; }

	[JsonProperty]
	public UnitFact MainFact { get; private set; }

	[JsonProperty]
	public Encumbrance Encumbrance { get; set; }

	[JsonProperty]
	public bool HasOwnInventory { get; private set; }

	[JsonProperty(NullValueHandling = NullValueHandling.Ignore)]
	public TimeSpan? LastRestTime { get; set; }

	[JsonProperty]
	[CanBeNull]
	private DollData Doll
	{
		set
		{
			m_LoadedDollData = value;
		}
	}

	public UnitEntityData Unit { get; private set; }

	public bool IsTurnedOn { get; private set; }

	public BlueprintFaction Faction
	{
		get
		{
			return m_Faction;
		}
		private set
		{
			m_Faction = value;
			m_IsPlayerFactionCached = m_Faction == BlueprintRoot.Instance.PlayerFaction;
			AttackFactions?.UpdateIsPlayerEnemy();
		}
	}

	public BlueprintFaction FactionOriginal => m_FactionOriginal ?? (m_FactionOriginal = Faction);

	public int Damage
	{
		get
		{
			return m_Damage;
		}
		set
		{
			m_Damage = Math.Max(0, value);
		}
	}

	public AbilityCollection Abilities => Unit.Abilities;

	public ActivatableAbilityCollection ActivatableAbilities => Unit.ActivatableAbilities;

	public BuffCollection Buffs => Unit.Buffs;

	public int DamageNonLethal => Stats.DamageNonLethal.ModifiedValue;

	public Gender Gender => CustomGender ?? Blueprint.Gender;

	public bool IsLeftHanded => LeftHandedOverride ?? Blueprint.IsLeftHanded;

	public string CharacterName
	{
		get
		{
			if ((bool)ReplaceBlueprintForInspection)
			{
				return ReplaceBlueprintForInspection.CharacterName;
			}
			if (!string.IsNullOrEmpty(CustomName))
			{
				return CustomName;
			}
			return Blueprint.CharacterName;
		}
	}

	[CanBeNull]
	public BlueprintUnitAsksList Asks
	{
		get
		{
			if (OverrideAsks != null)
			{
				return OverrideAsks;
			}
			if (CustomAsks != null)
			{
				return CustomAsks;
			}
			return Blueprint.Visual.Barks;
		}
	}

	public bool UseClassEquipment
	{
		get
		{
			if (!(Unit.PreviewOf.Entity != null))
			{
				if (!ForceUseClassEquipment && !Unit.IsMainCharacter)
				{
					return Unit.IsCustomCompanion();
				}
				return true;
			}
			return Unit.PreviewOf.Entity.Descriptor.UseClassEquipment;
		}
	}

	public Size OriginalSize => SimpleBlueprintExtendAsObject.Or(Progression.Race, null)?.Size ?? Blueprint.Size;

	public MechanicsContext Context
	{
		get
		{
			MechanicsContext obj = m_Context ?? (m_Context = new MechanicsContext(null, this, OriginalBlueprint));
			MechanicsContext result = obj;
			m_Context = obj;
			return result;
		}
	}

