	private static void AddStartingInventory(UnitDescriptor unit, BlueprintUnit blueprint)
	{
		if ((bool)ContextData<UnitEntityData.DoNotCreateItems>.Current)
		{
			return;
		}
		foreach (BlueprintItem item in blueprint.StartingInventory)
		{
			if ((bool)item)
			{
				using (ProfileScope.New("Add Item"))
				{
					using (ContextData<ItemsCollection.SuppressEvents>.Request())
					{
						unit.Inventory.Add(item);
					}
				}
			}
			else
			{
				PFLog.Default.Error("Unit '{0}' has NULL in StartingInventory", blueprint);
			}
		}
	}

	private static void InitializeStat(ModifiableValueAttributeStat stat, int value)
	{
		if ((bool)ContextData<UnitEntityData.DoNotInitializeStats>.Current)
		{
			value = 10;
		}
		if (value < 1)
		{
			stat.RetainDisabled();
		}
		else
		{
			stat.BaseValue = value;
		}
	}

	private void SetSkills(BlueprintUnit.UnitSkills skills)
