	{
		if (!Directory.Exists(Folder))
		{
			Directory.CreateDirectory(Folder);
		}
		string assetGuidThreadSafe = area.Blueprint.AssetGuidThreadSafe;
		fowMasks.SaveAll(Folder, assetGuidThreadSafe);
	}

