		{
			Directory.CreateDirectory(Folder);
		}
		byte[] bytes = tex.EncodeToPNG();
		string path = System.IO.Path.Combine(Folder, name + ".png");
		if (File.Exists(path))
		{
			File.Delete(path);
		}
		File.WriteAllBytes(path, bytes);
